const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '电源' },
      { kind: 'text', payload: '开关' },
      { kind: 'text', payload: '灯泡' },
      { kind: 'text', payload: '电流表' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var left = W * 0.20;
    var right = W * 0.78;
    var top = H * 0.24;
    var bottom = H * 0.76;
    var cx = (left + right) / 2;
    var midY = (top + bottom) / 2;
    var R = Math.min(W, H) * 0.055;
    var gapY = R * 1.5;
    var plateL = cx - R * 0.4;
    var plateR = cx + R * 0.4;
    var d = R / Math.SQRT2;
    var termR = Math.max(1.5, R * 0.12);

    var paths = [
      { id: 'wTopL', commands: [['M', left, top], ['L', cx - R, top]] },
      { id: 'wTopR', commands: [['M', cx + R, top], ['L', right, top]] },
      { id: 'wRightT', commands: [['M', right, top], ['L', right, midY - R]] },
      { id: 'wRightB', commands: [['M', right, midY + R], ['L', right, bottom]] },
      { id: 'wBotR', commands: [['M', plateR, bottom], ['L', right, bottom]] },
      { id: 'wBotL', commands: [['M', left, bottom], ['L', plateL, bottom]] },
      { id: 'wLeftB', commands: [['M', left, midY + gapY], ['L', left, bottom]] },
      { id: 'wLeftT', commands: [['M', left, top], ['L', left, midY - gapY]] },
      { id: 'batLong', commands: [['M', plateL, bottom - R * 0.95], ['L', plateL, bottom + R * 0.95]] },
      { id: 'batShort', commands: [['M', plateR, bottom - R * 0.55], ['L', plateR, bottom + R * 0.55]] },
      { id: 'swBlade', commands: [['M', left, midY + gapY], ['L', left + R * 1.6, midY - gapY * 0.8]] },
      { id: 'swTermA', commands: visualSdk.circle(left, midY - gapY, termR) },
      { id: 'swTermB', commands: visualSdk.circle(left, midY + gapY, termR) },
      { id: 'bulb', commands: visualSdk.circle(cx, top, R) },
      { id: 'bulbX1', commands: [['M', cx - d, top - d], ['L', cx + d, top + d]] },
      { id: 'bulbX2', commands: [['M', cx + d, top - d], ['L', cx - d, top + d]] },
      { id: 'meter', commands: visualSdk.circle(right, midY, R) }
    ];

    var nodes = [];
    var i;
    var wireIds = ['wTopL', 'wTopR', 'wRightT', 'wRightB', 'wBotR', 'wBotL', 'wLeftB', 'wLeftT', 'swBlade'];
    for (i = 0; i < wireIds.length; i++) {
      nodes.push({ type: 'path', pathId: wireIds[i], fill: '#1F2D3D', stroke: { width: 2, cap: 'round', join: 'round' } });
    }
    nodes.push({ type: 'path', pathId: 'batLong', fill: '#1F2D3D', stroke: { width: 3, cap: 'round' } });
    nodes.push({ type: 'path', pathId: 'batShort', fill: '#1F2D3D', stroke: { width: 3, cap: 'round' } });
    nodes.push({ type: 'path', pathId: 'swTermA', fill: '#1F2D3D', stroke: { width: 1 } });
    nodes.push({ type: 'path', pathId: 'swTermB', fill: '#1F2D3D', stroke: { width: 1 } });
    nodes.push({ type: 'path', pathId: 'bulb', fill: '#FFFFFF', stroke: { width: 2 } });
    nodes.push({ type: 'path', pathId: 'bulbX1', fill: '#1F2D3D', stroke: { width: 2, cap: 'round' } });
    nodes.push({ type: 'path', pathId: 'bulbX2', fill: '#1F2D3D', stroke: { width: 2, cap: 'round' } });
    nodes.push({ type: 'path', pathId: 'meter', fill: '#FFFFFF', stroke: { width: 2 } });

    nodes.push({ type: 'label', contentId: metrics[2].contentId, anchor: { x: cx, y: top - H * 0.06 }, hAlign: 'center', vAlign: 'bottom', color: '#1F2D3D' });
    nodes.push({ type: 'label', contentId: metrics[3].contentId, anchor: { x: right + R * 2.0, y: midY }, hAlign: 'center', vAlign: 'middle', color: '#1F2D3D' });
    nodes.push({ type: 'label', contentId: metrics[0].contentId, anchor: { x: cx, y: bottom + H * 0.09 }, hAlign: 'center', vAlign: 'top', color: '#1F2D3D' });
    nodes.push({ type: 'label', contentId: metrics[1].contentId, anchor: { x: left - R * 1.9, y: midY }, hAlign: 'center', vAlign: 'middle', color: '#1F2D3D' });

    return {
      schemaVersion: 1,
      sceneId: 'source-transcription-circuit',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: nodes }
    };
  }
};
